import gurobipy as gp

jobs = [1, 2, 3]
machines = [1, 2]
proces_time = [[1, 3], [2, 2], [3, 1]]

m = gp.Model()

start = {}
end = {}
for j in jobs:
    for m in machines:
        start[j, m] = m.addVar(name=f"start_{j}_{m}", lb=0)
        end[j, m] = m.addVar(name=f"end_{j}_{m}", lb=0)

m.update()

for j in jobs:
    for m in machines:
        m.addConstr(start[j, m] >= 0, name=f"c1_{j}_{m}")
        m.addConstr(end[j, m] >= 0, name=f"c2_{j}_{m}")
        m.addConstr(end[j, m] - start[j, m] >= proces_time[j-1][m-1], name=f"c3_{j}_{m}")
        m.addConstr(start[j, m] - end[j, m] <= 0, name=f"c4_{j}_{m}")
        m.addConstr(end[j, m] - start[j, m] <= proces_time[j-1][m-1], name=f"c5_{j}_{m}")
        if j < max(jobs):
            m.addConstr(end[j, m] - start[j+1, m] >= 0, name=f"c6_{j}_{m}")
            m.addConstr(start[j+1, m] - end[j, m] >= 0, name=f"c7_{j}_{m}")

m.setObjective(end[jobs[-1], machines[-1]], gp.GRB.MINIMIZE)

m.optimize()

print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

