import json
from gurobipy import *

m = Model()

# Variables
S = {(j,i): m.addVar(name=f"S_({j},{i})", lb=0) for j in range(6) for i in [0,1]}
C_max = m.addVar(name="C_max", lb=0)
X = {(j,i,k,l): m.addVar(name=f"X_({j},{i})_({k},{l})", vtype=GRB.BINARY) for j in range(6) for i in [0,1] for k in range(6) for l in [0,1] if (j != k or i != l)}

# Constraints
for j in range(6):
    for i in [0,1]:
        m.addConstr(S[(j,i)] >= 0, name=f"c1_{j}_{i}")
        m.addConstr(C_max >= S[(j,i)] + 1, name=f"c2_{j}_{i}")

# Objective
m.setObjective(C_max, GRB.MINIMIZE)

# Add constraints for non-overlapping operations on the same machine
for j in range(6):
    for i in [0,1]:
        for k in range(6):
            for l in [0,1]:
                if j != k or i != l:
                    m.addConstr(S[(j,i)] + X[(j,i,k,l)] <= S[(k,l)] + 1, name=f"c3_{j}_{i}_{k}_{l}")
                    m.addConstr(S[(k,l)] + (1 - X[(j,i,k,l)]) <= S[(j,i)] + 1, name=f"c4_{j}_{i}_{k}_{l}")

m.optimize()

print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

