import json
import gurobipy as gp

m = gp.Model()

# Variables
start_j_m = {}
makespan = m.addVar(name="makespan", lb=0, ub=None, vtype='C')

# Processing times
processing_times = {
    (1, 0): 17, (1, 1): 25, (1, 2): 6,
    (2, 0): 25, (2, 1): 18, (2, 2): 7,
    (3, 0): 17, (3, 1): 27, (3, 2): 15,
    (4, 0): 16, (4, 1): 25, (4, 2): 7
}

# Machine assignments
machine_assignments = {
    (1, 0): 0, (1, 1): 2, (1, 2): 1,
    (2, 0): 2, (2, 1): 1, (2, 2): 0,
    (3, 0): 0, (3, 1): 1, (3, 2): 2,
    (4, 0): 0, (4, 1): 1, (4, 2): 2
}

# Add variables for start times
for j in range(1, 5):
    for m in range(3):
        start_j_m[(j, m)] = m.addVar(name=f"start_{j}_{m}", lb=0, ub=None, vtype='C')

# Constraints
for j in range(1, 5):
    for m in range(3):
        m.addConstr(start_j_m[(j, m)] >= 0, name=f"c1_{j}_{m}")
        for j_prime in range(1, 5):
            if j_prime != j:
                for m_prime in range(3):
                    if machine_assignments[(j, m)] == machine_assignments[(j_prime, m_prime)]:
                        m.addConstr(start_j_m[(j, m)] - start_j_m[(j_prime, m_prime)] >= 0, name=f"c2_{j}_{m}_{j_prime}_{m_prime}")
        m.addConstr(start_j_m[(j, m)] - makespan <= 0, name=f"c3_{j}_{m}")
        for j_prime in range(1, 5):
            if j_prime == j + 1:
                for m_prime in range(3):
                    if machine_assignments[(j, m)] == machine_assignments[(j_prime, m_prime)]:
                        m.addConstr(start_j_m[(j, m)] + processing_times[(j, m)] <= start_j_m[(j_prime, m_prime)], name=f"c4_{j}_{m}_{j_prime}_{m_prime}")

# Objective
m.setObjective(makespan, gp.GRB.MINIMIZE)

# Optimize
m.optimize()

print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

