start = {(j, m, op): m.addVar(name=f'start_{j}_{m}_{op}', lb=0, ub=None, vtype='C') for j in jobs for m in machines for op in operations if processing_time[j][m][op] is not None}
makespan = m.addVar(name='makespan', lb=0, ub=None, vtype='C')

