                # Makespan constraint
                m.addConstr(makespan >= start[j, m, op] + processing_time[j][m][op], name=f'c4_{j}_{m}_{op}')

# Objective
m.setObjective(makespan, gp.GRB.MINIMIZE)

# Optimize
m.optimize()

print(json.dumps({"objective_value": float(m.ObjVal), "assignment": {v.VarName: v.X for v in m.getVars()}}))

